def cholesky_decomposition(matrix):
    if not GSLMatrix(matrix).is_positive_definite():
        raise ValueError("Matrix is not positive definite.")

    m = len(matrix)
    L = [[0 for _ in range(m)] for _ in range(m)]
    gsl_mat = (ctypes.c_double * m * m)(*[(x[y] if isinstance(x, list) and isinstance(y, int)) else 0 for x in matrix for y in range(len(matrix[0]))])
    res = gsl.gsl_linalg_cholesky_decomp(ctypes.cast(gsl_mat, ctypes.POINTER(ctypes.c_double * 1)))
    if res != 0:
        raise RuntimeError("Cholesky decomposition failed.")
    for i in range(m):
        for j in range(i + 1):
            L[i][j] = gsl_mat[i * m + j]
    return L

