class GslRstatQuantileWorkspace:
    def __init__(self):
        self._workspace = None

    def compute_quantile(self, p: float, values: List[float]) -> float:
        if self._workspace is None:
            raise ValueError("Workspace not initialized.")

        gsl.gsl_rstat_quantile_add.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_long]
        gsl.gsl_rstat_quantile_add.restype = None

        for value in values:
            gsl.gsl_rstat_quantile_add(ctypes.cast(self._workspace, ctypes.POINTER(ctypes.c_double)), value, len(values))

        result = gsl.gsl_rstat_quantile_get(self._workspace, p)

        return result

    def allocate(self, n: int) -> None:
        self._workspace = gsl.gsl_rstat_quantile_alloc(n)
        if self._workspace is None:
            raise MemoryError("Workspace allocation failed.")

    def reset(self) -> None:
